/** Opaque secret and credential handles. */
import type { Credentials, Secret, SecretPurpose, Secrets } from './types.ts';
/** One secret as the registry knows it: its name and what it is for. */
interface RegisteredSecret {
    readonly name: string;
    readonly purpose: SecretPurpose;
}
/**
 * What the handles resolve against, as the resolved config carries it: the
 * run's accounts, the `config.secrets` entries, and every secret the run
 * holds. Named structurally rather than picked from `ResolvedConfig`, so the
 * public `secrets` surface pulls no config module, and none of its imports,
 * into a consumer's types.
 */
export interface SecretRegistry {
    readonly credentials: ReadonlyMap<string, {
        readonly name: string;
        readonly username: string;
        readonly password: RegisteredSecret;
    }>;
    readonly secrets: ReadonlyMap<string, RegisteredSecret>;
    readonly allSecrets: ReadonlyMap<string, RegisteredSecret>;
}
/** Async-local and realm-shared: concurrent attempts keep their own registry untouched. */
export declare function withConfigSecretReferences<T>(load: () => T): T;
/** Installed by the runner once config resolution completes. */
export declare function setSecretRegistry(registry: SecretRegistry | undefined): void;
/**
 * Installs `registry` for a standalone worker or attempt until the returned
 * release runs. Several may hold one at once, as live sessions do: releasing
 * one installs the newest registry still held, and releasing the last clears
 * the slot, so closing one session never leaves another resolving against
 * none. A `live` hold is an attempt's: it outranks a worker that opens while
 * the attempt runs, whose config would otherwise capture the attempt's handles.
 */
export declare function holdSecretRegistry(registry: SecretRegistry, options?: {
    readonly live?: boolean;
}): () => void;
/**
 * The code an unresolvable secret fails with: a credential's password is a
 * credential problem, any other secret a secret problem.
 */
export declare function unavailableCode(secret: Pick<Secret, 'purpose'>): 'AUTH_CREDENTIAL_UNAVAILABLE' | 'SECRET_UNAVAILABLE';
/** The opaque handle of a secret the registry holds, for a host that hands every configured secret to a step (`e2e mcp`). */
export declare function secretHandle({ name, purpose }: RegisteredSecret): Secret;
/** Whether a value is a `Secret` handle, from this module instance or another realm's. */
export declare function isSecret(value: unknown): value is Secret;
export declare const credentials: Credentials;
export declare const secrets: Secrets;
export {};
